# Meerdere rollen per account (Rol) en rolaanvragen (Rolaanvraag). Bestaande rollen worden overgenomen.

import django.db.models.deletion
from django.conf import settings
from django.db import migrations, models


def rollen_overnemen(apps, schema_editor):
    """Elk account houdt zijn rol: de enige rol uit Profiel.rol wordt de eerste rij in Rol.
    Superusers waren altijd beheerder; ook dat wordt nu bewaard. Accounts zonder profiel waren zwemmer."""
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    Profiel = apps.get_model("inschrijvingen", "Profiel")
    Rol = apps.get_model("inschrijvingen", "Rol")
    profielen = {p.user_id: p.rol for p in Profiel.objects.all()}
    nieuw = []
    for u in User.objects.all():
        rollen = {profielen.get(u.pk, "zwemmer")}
        if u.is_superuser:
            rollen.add("beheerder")
        nieuw += [Rol(user_id=u.pk, rol=r) for r in sorted(rollen)]
    Rol.objects.bulk_create(nieuw)
    Profiel.objects.filter(user__is_superuser=True).update(rol="beheerder")  # hoofdrol = hoogste rol


def rollen_terug(apps, schema_editor):
    """Terug naar één rol: de hoofdrol in Profiel.rol blijft; de nieuwe rollen worden zwemmer."""
    Profiel = apps.get_model("inschrijvingen", "Profiel")
    Profiel.objects.filter(rol__in=["ouder", "bestuurder"]).update(rol="zwemmer")


